 "content": "from collections import deque


def transform(grid):
    """Copy the one patterned rectangle's interior into empty same-sized frames.

    Frames whose inner dimensions do not match the motif are removed; the
    patterned source frame is retained.
    """
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = a[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and a[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            boxes.append((color, min(ys), max(ys), min(xs), max(xs)))

    # In these puzzles each frame is a solid rectangular perimeter, so its
    # bounding box determines the interior dimensions. Find the sole frame
    # whose interior contains colored cells.
    sources = []
    for color, r0, r1, c0, c1 in boxes:
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        motif = [[a[r][c] == color for c in range(c0+1, c1)]
                 for r in range(r0+1, r1)]
        if any(any(row) for row in motif):
            sources.append((color, r0, r1, c0, c1, motif))
    if not sources:
        return a
    # The task has one patterned frame; retain it as the template.
    sc, sr0, sr1, sc0, sc1, motif = sources[0]
    mh, mw = len(motif), len(motif[0])

    for color, r0, r1, c0, c1 in boxes:
        if (color, r0, r1, c0, c1) == (sc, sr0, sr1, sc0, sc1):
            continue
        ih, iw = r1-r0-1, c1-c0-1
        if (ih, iw) == (mh, mw):
            for i in range(mh):
                for j in range(mw):
                    a[r0+1+i][c0+1+j] = color if motif[i][j] else 0
        else:
            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    if a[r][c] == color:
                        a[r][c] = 0
    return a
